# Shared capture/work vectors: extension-protocol/go/rhunext/testdata/snippet-regex.json.
# Regenerate payload in that repository with RHUN_REGEX_ASM_OUT=/tmp/regex-vectors.s
# go test ./go/rhunext -run '^TestSnippetRegexNativeVectorExport$'; replace after the marker below.
.include "rhun.inc"
.bss
.p2align 3
out: .zero SB_SIZE
.text
FN main
    PROLOGUE
    mov r15, [rip + g_mem_live]
    lea r12, [rip + .Lrxmatch_vectors]
    xor r13d, r13d
.Lcase:
    cmp qword ptr [r12], 0
    je .Lok
    xor ebx, ebx
    mov edi, RX_WORK_MAX
    xor esi, esi
    call snippet_regex_new
    test rax, rax
    jz .Lfail
    mov rbx, rax
    mov rdi, rbx
    mov rsi, [r12]
    mov rdx, [r12 + 8]
    mov rcx, [r12 + 16]
    mov r8, [r12 + 24]
    call snippet_regex_open
    test eax, eax
    jz .Lfail
    mov rdi, rbx
    mov rsi, [r12 + 32]
    call snippet_regex_find
    cmp rax, [r12 + 40]
    jne .Lfail
    cmp rax, [rbx + RX_hasmatch]
    jne .Lfail
    test eax, eax
    jz 1f
    lea rdi, [rbx + RX_captures]
    mov rsi, [r12 + 56]
    mov rdx, [r12 + 48]
    shl rdx, 4
    call memeq
    test eax, eax
    jz .Lfail
    mov rax, [r12 + 56]
    mov rcx, [rax]
    cmp rcx, [rbx + RX_start]
    jne .Lfail
    mov rcx, [rax + 8]
    cmp rcx, [rbx + RX_end]
    jne .Lfail
1:  mov rax, [r12 + 64]
    cmp rax, [rbx + RX_work]
    jne .Lfail
    mov rdi, rbx
    call snippet_regex_free
    xor ebx, ebx
    cmp r15, [rip + g_mem_live]
    jne .Lfail
    inc r13
    add r12, 72
    jmp .Lcase
.Lok:
    lea rdi, [rip + ok]
    call log_cstr
    xor eax, eax
    EPILOGUE
.Lfail:
    lea rdi, [rip + failed]
    call log_cstr
    lea rdi, [rip + out]
    mov rsi, r13
    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 32
    call sb_push_byte
    lea rdi, [rip + out]
    xor esi, esi
    test rbx, rbx
    jz 2f
    mov rsi, [rbx + RX_error]
2:    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 32
    call sb_push_byte
    lea rdi, [rip + out]
    xor esi, esi
    test rbx, rbx
    jz 3f
    mov rsi, [rbx + RX_errpc]
3:    call sb_push_u64
    lea rdi, [rip + out]
    mov esi, 10
    call sb_push_byte
    mov rdi, [rip + out + SB_ptr]
    mov rsi, [rip + out + SB_len]
    call log_write
    mov eax, 1
    EPILOGUE
.section .rodata
ok: .asciz "ok snippet regex matcher\n"
failed: .asciz "failed snippet regex matcher case/error/pc "
